// Scene 4 stage: runs the genuine standalone custom element generated by `automatonEmbed` from a
// Blob script, paired with its two-line HTML snippet and one-click `Copy for a coding agent`.

import { createElement, useEffect, useMemo, useState } from "react";
import { Link } from "react-router";
import { fill, SITE_WORDS } from "../../app/site-words";
import { agentBrief, automatonEmbed, automatonTagName, embedSnippet, type AutomatonEmbed } from "../../replay/automaton-embed";
import { makerLine } from "../../replay/material-facts";
import { EXPORT_FRAGMENT } from "../../replay/material-stage";
import { downloadBlob } from "../../ui/files";
import { Segmented } from "../../ui/segmented";
import { groupPath } from "../automata/gallery";
import { nameOf, type BasisGroupNames } from "../gallery/basis-groups";
import { materialFileUrl, usePublishedMaterial } from "../gallery/material-gallery";
import type { MaterialEntry } from "../gallery/material-index";
import type { HomeStill } from "./home-material-view";
import { resolveKeepCandidates } from "./home-specimens";

const WORDS = SITE_WORDS.home.keep;
const STAGE_WORDS = SITE_WORDS.stage;

/** Executes the generated standalone embed script once per tag so `<dinodreamer-...>` registers itself. */
function useRegisteredEmbed(embed: AutomatonEmbed | null): void {
  useEffect(() => {
    if (!embed || customElements.get(embed.tagName)) return;
    const url = URL.createObjectURL(new Blob([embed.script], { type: "text/javascript" }));
    const script = document.createElement("script");
    script.src = url;
    const revoke = () => URL.revokeObjectURL(url);
    script.addEventListener("load", revoke, { once: true });
    script.addEventListener("error", revoke, { once: true });
    document.head.append(script);
  }, [embed]);
}

export function HomeKeepStage({ entries, names, approached, active, still }: {
  entries: readonly MaterialEntry[];
  names: BasisGroupNames;
  approached: boolean;
  active: boolean;
  still: HomeStill;
}) {
  const candidates = resolveKeepCandidates(entries);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [feedback, setFeedback] = useState<{ entryId: string; text: string } | null>(null);

  const entry = candidates.find((candidate) => candidate.id === selectedId) ?? candidates[0] ?? null;
  const material = usePublishedMaterial(approached ? entry : null);
  const loaded = material.status === "ready" ? material.value : null;
  const definition = loaded ? loaded.file : null;
  const entryTitle = entry?.title ?? "";
  const entryCredit = entry?.credit ?? "";

  const embed = useMemo(
    () => (definition ? automatonEmbed(definition, { title: entryTitle, credit: entryCredit }) : null),
    [definition, entryTitle, entryCredit],
  );
  useRegisteredEmbed(embed);

  const previewTag = entry ? automatonTagName({ id: entry.materialId, block: entry.block }) : "dinodreamer-12002-000000";
  const snippet = embed
    ? embedSnippet(embed)
    : embedSnippet({ tagName: previewTag, fileName: `${previewTag}.js` });

  const defaultNames = WORDS.groupDefaultNames as Record<number, string | undefined>;
  const groupName = entry ? (nameOf(names, entry.block) ?? defaultNames[entry.block] ?? null) : null;
  const maker = entry
    ? (loaded
        ? makerLine({ title: entry.title, credit: entry.credit }, loaded.file)
        : entry.credit ? fill(STAGE_WORDS.by, { credit: entry.credit }) : "")
    : "";

  const segments = candidates.map((candidate) => {
    const labelName = nameOf(names, candidate.block) ?? defaultNames[candidate.block];
    return {
      value: candidate.id,
      label: labelName ? `${candidate.block} · ${labelName}` : String(candidate.block),
    };
  });

  const copyForAgent = () => {
    if (!embed || !loaded || !entry) return;
    downloadBlob(new Blob([embed.script], { type: "text/javascript" }), embed.fileName);
    navigator.clipboard.writeText(agentBrief(embed, loaded.file)).then(
      () => setFeedback({ entryId: entry.id, text: STAGE_WORDS.copiedForAgent }),
      (error: unknown) => setFeedback({
        entryId: entry.id,
        text: fill(STAGE_WORDS.copyFailed, { message: String(error instanceof Error ? error.message : error) }),
      }),
    );
  };

  const shownFeedback = feedback && entry && feedback.entryId === entry.id ? feedback.text : null;

  return (
    <div className="home-stage-frame home-keep">
      {segments.length > 1 && entry && (
        <Segmented
          label={WORDS.choiceName}
          segments={segments}
          value={entry.id}
          onChange={setSelectedId}
        />
      )}

      <div
        className="home-keep-canvas"
        style={entry && !embed ? { backgroundImage: `url(${materialFileUrl(entry, "poster.png")})` } : undefined}
      >
        {embed && createElement(embed.tagName, {
          key: embed.tagName,
          draw: "",
          ...(active && !still ? {} : { paused: "" }),
        })}
      </div>

      {entry && (
        <p className="home-stage-caption">
          <span>
            {[
              `Group ${entry.block}`,
              groupName,
              maker || null,
            ].filter(Boolean).join(" · ")}
          </span>
          <span className="label">{WORDS.standalone}</span>
        </p>
      )}

      <pre className="home-keep-snippet" aria-label={WORDS.snippetLabel}>
        <code>{snippet}</code>
      </pre>

      <div className="home-keep-actions">
        <button
          type="button"
          className="button"
          disabled={!embed || !loaded}
          onClick={copyForAgent}
        >
          {WORDS.copyForAgent}
        </button>
        {entry && (
          <Link className="button" to={`${groupPath(entry.block, entry.id)}${EXPORT_FRAGMENT}`}>
            {WORDS.moreExports}
          </Link>
        )}
      </div>
      {shownFeedback && <p className="home-keep-feedback" role="status">{shownFeedback}</p>}
    </div>
  );
}
